<script setup>defineProps({app:Object});defineEmits(['open','favorite'])</script><template><article class="card"><div class="row between"><div class="icon">{{app.icon}}</div><button class="btn alt" @click="$emit('favorite',app)">{{app.favorite?'★':'☆'}}</button></div><h3>{{app.name}}</h3><p class="muted">{{app.description||app.category}}</p><button class="btn" @click="$emit('open',app)">Buka aplikasi ↗</button></article></template>